import "bare-node-runtime/global";
import Module from "module";
import { aggregateFrost, computeMultiInputSighash, constructNodeTxPair, constructRefundTxTrio, createDummyTx, decryptEcies, encryptEcies, recoverSecret, signFrost, splitSecretWithProofs, validateShare } from "@buildonspark/spark-frost-bare-addon";
import { DefaultSparkSigner, SparkFrostBase, SparkValidationError, getSparkFrost, setSparkFrostOnce } from "@buildonspark/spark-sdk/bare";

export * from "@buildonspark/spark-sdk/bare"

//#region src/bare-signer.ts
/**
* @deprecated It's no longer necessary to provide BareSparkSigner when
* initializing a SparkWallet and it will be removed in a future release.
*/
var BareSparkSigner = class extends DefaultSparkSigner {
	async signFrost({ message, publicKey, verifyingKey, selfCommitment, statechainCommitments, keyDerivation, adaptorPubKey }) {
		const signingPrivateKey = await this.getSigningPrivateKeyFromDerivation(keyDerivation);
		if (!signingPrivateKey) throw new SparkValidationError("Private key not found for public key", { field: "privateKey" });
		const commitment = selfCommitment.commitment;
		const nonce = this.commitmentToNonceMap.get(commitment);
		if (!nonce) throw new SparkValidationError("Nonce not found for commitment", { field: "nonce" });
		const keyPackage = {
			secretKey: signingPrivateKey,
			publicKey,
			verifyingKey
		};
		return getSparkFrost().signFrost({
			message,
			keyPackage,
			nonce,
			selfCommitment: selfCommitment.commitment,
			statechainCommitments,
			adaptorPubKey
		});
	}
	async aggregateFrost({ message, statechainCommitments, selfCommitment, statechainSignatures, selfSignature, statechainPublicKeys, publicKey, verifyingKey, adaptorPubKey }) {
		return getSparkFrost().aggregateFrost({
			message,
			statechainCommitments,
			selfCommitment: selfCommitment.commitment,
			statechainSignatures,
			selfSignature,
			statechainPublicKeys,
			selfPublicKey: publicKey,
			verifyingKey,
			adaptorPubKey
		});
	}
};

//#endregion
//#region src/entry.ts
Object.defineProperty(Module, "_resolveFilename", {
	value: () => {
		throw new Error("@buildonspark/bare: This method is not supported in bare.");
	},
	writable: false,
	enumerable: false,
	configurable: false
});
var SparkFrostBare = class extends SparkFrostBase {
	signFrost({ message, keyPackage, nonce, selfCommitment, statechainCommitments, adaptorPubKey }) {
		return signFrost(message, keyPackage, nonce, selfCommitment, statechainCommitments ? Object.entries(statechainCommitments) : [], adaptorPubKey || new Uint8Array(0));
	}
	aggregateFrost({ message, statechainCommitments, selfCommitment, statechainSignatures, selfSignature, statechainPublicKeys, selfPublicKey, verifyingKey, adaptorPubKey }) {
		return aggregateFrost(message, statechainCommitments ? Object.entries(statechainCommitments) : [], selfCommitment, statechainSignatures ? Object.entries(statechainSignatures) : [], selfSignature, statechainPublicKeys ? Object.entries(statechainPublicKeys) : [], selfPublicKey, verifyingKey, adaptorPubKey || new Uint8Array(0));
	}
	createDummyTx(address, amountSats) {
		return createDummyTx(address, amountSats);
	}
	encryptEcies(msg, publicKey) {
		return encryptEcies(msg, publicKey);
	}
	decryptEcies(encryptedMsg, privateKey) {
		return decryptEcies(encryptedMsg, privateKey);
	}
	splitSecretWithProofs(secret, threshold, numShares) {
		const result = splitSecretWithProofs(secret, threshold, numShares);
		return Promise.resolve(result.map((s) => ({
			threshold: s.threshold,
			index: s.index,
			share: new Uint8Array(s.share),
			proofs: s.proofs.map((p) => new Uint8Array(p))
		})));
	}
	recoverSecret(shares) {
		const result = recoverSecret(shares);
		return Promise.resolve(result);
	}
	validateShare(share, index, threshold, proofs) {
		validateShare(share, index, threshold, proofs);
		return Promise.resolve();
	}
	constructNodeTxPair(parentTx, vout, address, sequence, directSequence, feeSats) {
		return constructNodeTxPair(new Uint8Array(parentTx), vout, address, sequence, directSequence, feeSats);
	}
	constructRefundTxTrio(cpfpNodeTx, directNodeTx, vout, receivingPubkey, network, sequence, directSequence, feeSats) {
		return constructRefundTxTrio(new Uint8Array(cpfpNodeTx), directNodeTx ? new Uint8Array(directNodeTx) : new Uint8Array(0), vout, new Uint8Array(receivingPubkey), network, sequence, directSequence, feeSats);
	}
	computeMultiInputSighash(tx, inputIndex, prevOutScripts, prevOutValues) {
		return computeMultiInputSighash(new Uint8Array(tx), inputIndex, prevOutScripts.map((s) => new Uint8Array(s)), prevOutValues);
	}
};
setSparkFrostOnce(new SparkFrostBare());

//#endregion
export { BareSparkSigner };